// Format Probe
// -----------------------------------------------------------------------------
// Two bugs fixed here.
//
// 1. NO VERDICT. 'WAHA Sessions' runs with neverError: true AND
//    onError: continueRegularOutput. neverError only swallows non-2xx HTTP
//    STATUSES; a dead container is a transport error (ECONNREFUSED), which
//    onError then turns into a data item carrying `error`. Either way the old
//    code emitted status: null and 'Respond' still answered HTTP 200 -- a dead
//    WhatsApp channel was indistinguishable from a healthy one. This node now
//    computes `ok` and the caller is routed to a 200 or a 503.
//
// 2. LEAKING THE MAP. The old output included connected_number and every WAHA
//    webhook URL, on an unauthenticated endpoint. Those are now emitted only
//    when NEXUS_PROBE_VERBOSE=true.
//
// NOTE FOR WHOEVER EDITS THIS NEXT: the upstream response `s` contains
// config.webhooks[].customHeaders, which -- once the WhatsApp webhook secret is
// installed -- CONTAINS THAT SECRET. Never pass `s` or `s.config` through to the
// output. Build the response field by field, as below.
const r = $input.first().json || {};

const transportError = r.error !== undefined && r.error !== null;
const code = Number(r.statusCode == null ? 0 : r.statusCode);
const httpOk = code >= 200 && code < 300;

const s = (!transportError && r.body !== undefined && r.body !== null) ? r.body
        : (!transportError ? r : {});

const sessionStatus = (s && s.status) || null;
const cfg   = (s && s.config) || {};
const hooks = (cfg.webhooks || []);
const connectedNumber = (s && s.me && s.me.id) || null;

const reasons = [];
if (transportError) {
  reasons.push('waha unreachable: ' + String((r.error && (r.error.message || r.error.description)) || r.error).slice(0, 160));
} else {
  if (!httpOk) reasons.push('waha http ' + (code || 'none'));
  if (sessionStatus !== 'WORKING') reasons.push('session status ' + (sessionStatus || 'unknown'));
  if (!connectedNumber) reasons.push('no connected number');
  if (hooks.length === 0) reasons.push('no webhooks configured');
}

const ok = reasons.length === 0;

const out = {
  probe: 'waha (GCP container)',
  ok: ok,
  verdict: ok ? 'PASS' : 'FAIL',
  reasons: reasons,
  session_status: sessionStatus,
  number_connected: !!connectedNumber,
  webhook_count: hooks.length,
  checked_at: new Date().toISOString()
};

// Detail is opt-in and stays off by default. Turn it on only while debugging,
// and only while NEXUS_PROBE_KEY is also set.
if (String($env.NEXUS_PROBE_VERBOSE || '').trim().toLowerCase() === 'true') {
  out.detail = {
    session: (s && s.name) || null,
    http_status: transportError ? null : code,
    connected_number: connectedNumber,
    webhooks: hooks.map(h => ({ url: h.url, events: h.events }))
  };
}

return [{ json: out }];

// Probe Auth Gate
// -----------------------------------------------------------------------------
// GET/POST /webhook/infra-probe used to be open to the internet and answered
// with the connected WhatsApp number and the full WAHA webhook URL list -- i.e.
// it handed an attacker the address of /webhook/whatsapp-inbound. Two changes
// close that: this gate, and 'Format Probe' no longer emitting those fields
// unless NEXUS_PROBE_VERBOSE=true.
//
// Unlike the WhatsApp webhook, this one uses responseMode: responseNode, so a
// rejected caller can be given a real 401 -- but only by ROUTING to a Respond
// node. Returning [] here would leave the request hanging until n8n's webhook
// timeout, so this node always emits exactly one item and lets
// 'Probe Authorized?' decide.
//
// DORMANT when NEXUS_PROBE_KEY is unset: authorized = true, behaviour unchanged.
// That is the rollback (comment the var out of /opt/nexus/.env, restart n8n).
const EXPECTED = String($env.NEXUS_PROBE_KEY || '');
const HEADER   = 'x-nexus-probe-key';

const item = $input.first() || { json: {} };
const headers = (item.json && item.json.headers) || {};
const query   = (item.json && item.json.query) || {};

let got = '';
for (const k of Object.keys(headers)) {
  if (String(k).toLowerCase() === HEADER) { got = String(headers[k] == null ? '' : headers[k]); break; }
}
// Accept ?key= as well, so the probe stays checkable from a phone browser or a
// plain `curl`. A query string is weaker than a header (it lands in access logs
// and browser history) -- use the header where you can.
if (!got && query && query.key) got = String(query.key);

function sameSecret(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const authorized = !EXPECTED || (got !== '' && sameSecret(got, EXPECTED));

return [{ json: { authorized: authorized, gate_dormant: !EXPECTED }, pairedItem: { item: 0 } }];

// Probe Alarm
// -----------------------------------------------------------------------------
// The probe had no caller: nothing ran it on a schedule, so 'WAHA is down' was
// only ever discovered by a human opening a browser. 'Every 15 Minutes' now runs
// the same chain, and this node turns a FAIL into a thrown error, which n8n
// routes to the workflow's configured error workflow (iYJkh1kztWxZXDbT).
//
// It deliberately does NOT throw on every failing run. WAHA can be down for
// hours; 4 alerts an hour would train everyone to ignore them. Static workflow
// data (persisted between PRODUCTION executions) counts consecutive failures and
// throws on the 1st, then every 8th (~ every 2 hours) until it recovers.
//
// This node sits to the RIGHT and BELOW both Respond nodes on purpose: under
// executionOrder v1 branch order follows node position, so the HTTP response is
// already sent before this throws. A webhook probe still gets its 200/503.
const st = $getWorkflowStaticData('global');
const j = $input.first().json || {};

if (j.ok === true) {
  const was = Number(st.wahaConsecutiveFailures || 0);
  st.wahaConsecutiveFailures = 0;
  return [{ json: { alarm: 'clear', recovered: was > 0, previous_consecutive_failures: was } }];
}

const n = Number(st.wahaConsecutiveFailures || 0) + 1;
st.wahaConsecutiveFailures = n;

if (n === 1 || n % 8 === 0) {
  throw new Error(
    'WAHA HEALTH PROBE FAIL (' + n + ' consecutive check' + (n === 1 ? '' : 's') + '): ' +
    (j.reasons || []).join('; ') +
    ' -- the dealership WhatsApp channel may be down.'
  );
}

return [{ json: { alarm: 'suppressed', consecutive_failures: n, reasons: j.reasons || [] } }];
